from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0])
    seen=set(); objs=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==0 or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                rr,cc=q.pop(); cells.append((rr,cc))
                for nr,nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0<=nr<h and 0<=nc<w and grid[nr][nc]==color and (nr,nc) not in seen:
                        seen.add((nr,nc));q.append((nr,nc))
            r0=min(x for x,y in cells); r1=max(x for x,y in cells); c0=min(y for x,y in cells); c1=max(y for x,y in cells)
            rel={(x-r0,y-c0) for x,y in cells}
            ring=all((rr,cc) in rel for rr in range(r1-r0+1) for cc in range(c1-c0+1) if rr in (0,r1-r0) or cc in (0,c1-c0))
            objs.append({'color':color,'cells':rel,'r':r0,'c':c0,'h':r1-r0+1,'w':c1-c0+1,'ring':ring})
    out=[[0]*w for _ in range(h)]
    # pack rings upward; all others downward, respecting original vertical ordering where x ranges overlap.
    for ring, direction in ((True,-1),(False,1)):
        group=[o for o in objs if o['ring']==ring]
        group.sort(key=lambda o:o['r'] if direction<0 else -(o['r']+o['h']-1))
        placed=[]
        for o in group:
            nr=o['r']
            while True:
                cand=nr+direction
                if cand<0 or cand+o['h']>h: break
                collides=False
                for p,pr in placed:
                    if not (o['c']+o['w']-1 < p['c'] or p['c']+p['w']-1 < o['c']):
                        # Check pixel overlap at candidate vertical position
                        if any((cand+rr, o['c']+cc) in {(pr+ar,p['c']+ac) for ar,ac in p['cells']} for rr,cc in o['cells']):
                            collides=True;break
                if collides: break
                nr=cand
            placed.append((o,nr))
            for rr,cc in o['cells']:
                out[nr+rr][o['c']+cc]=o['color']
    return out

